const schema = ({ path, title, description, serviceName = '', article = null }) => {
  const labels = { about: 'About', services: 'Services', blog: 'Blog', contact: 'Contact', faq: 'FAQ', 'web-design': 'Web Design & Development', seo: 'SEO', 'ui-ux': 'UI/UX & Brand Design', 'digital-marketing': 'Digital Marketing', ecommerce: 'E-Commerce', maintenance: 'Maintenance & Support', 'small-business-website-cost-los-angeles': 'Small-Business Website Cost in Los Angeles', 'local-seo-los-angeles-starter-guide': 'Local SEO for Los Angeles Businesses' };
  const segments = path.split('/').filter(Boolean);
  const breadcrumb = [{ '@type': 'ListItem', position: 1, name: 'Home', item: `${domain}/` }];
  segments.forEach((segment, index) => breadcrumb.push({ '@type': 'ListItem', position: index + 2, name: labels[segment] || segment, item: `${domain}/${segments.slice(0, index + 1).join('/')}` }));
  const webpage = { '@type': path === '/blog' ? ['WebPage', 'CollectionPage'] : 'WebPage', '@id': `${domain}${path}#webpage`, url: `${domain}${path}`, name: title, description, isPartOf: { '@id': `${domain}/#website` }, about: { '@id': `${domain}/#business` }, breadcrumb: { '@id': `${domain}${path}#breadcrumb` }, inLanguage: 'en-US', dateModified: modifiedDate };
  if (article) webpage.mainEntity = { '@id': `${domain}${path}#article` };
  const graph = [
    { '@type': 'WebSite', '@id': `${domain}/#website`, url: `${domain}/`, name: 'NuvelloWeb', publisher: { '@id': `${domain}/#business` }, inLanguage: 'en-US' },
    { '@type': ['ProfessionalService', 'LocalBusiness'], '@id': `${domain}/#business`, name: 'NuvelloWeb LLC', alternateName: 'NuvelloWeb', url: `${domain}/`, logo: { '@type': 'ImageObject', url: `${domain}/assets/brand/icon-512.png`, width: 512, height: 512 }, image: `${domain}/assets/og.png`, telephone: '+13232199208', email: 'contact@nuvelloweb.com', founder: { '@id': `${domain}/about#founder` }, address: { '@type': 'PostalAddress', addressLocality: 'Los Angeles', addressRegion: 'CA', addressCountry: 'US' }, areaServed: [{ '@type': 'City', name: 'Los Angeles' }, { '@type': 'Country', name: 'United States' }], sameAs: ['https://www.facebook.com/nuvellowebllc', 'https://www.linkedin.com/company/nuvello-web/', 'https://instagram.com/nuvelloweb'], knowsAbout: ['Web design', 'Web development', 'Search engine optimization', 'User experience design', 'Digital marketing', 'E-commerce'] },
    { '@type': 'Person', '@id': `${domain}/about#founder`, name: 'Benjamin Krikler', jobTitle: 'Founder', url: `${domain}/about`, image: `${domain}/assets/Images/BenKrikler2.jpeg`, worksFor: { '@id': `${domain}/#business` } },
    webpage,
    { '@type': 'BreadcrumbList', '@id': `${domain}${path}#breadcrumb`, itemListElement: breadcrumb }
  ];
  if (serviceName) graph.push({ '@type': 'Service', '@id': `${domain}${path}#service`, name: serviceName, url: `${domain}${path}`, description, provider: { '@id': `${domain}/#business` }, areaServed: [{ '@type': 'City', name: 'Los Angeles' }, { '@type': 'Country', name: 'United States' }] });
  if (article) {
    const post = { '@type': 'BlogPosting', '@id': `${domain}${path}#article`, headline: title, description, datePublished: article.datePublished, dateModified: modifiedDate, author: { '@id': `${domain}/about#founder` }, publisher: { '@id': `${domain}/#business` }, mainEntityOfPage: { '@id': `${domain}${path}#webpage` }, articleSection: article.section, keywords: article.keywords, inLanguage: 'en-US' };
    if (article.image) post.image = { '@type': 'ImageObject', url: `${domain}${article.image}`, width: article.imageWidth, height: article.imageHeight };
    graph.push(post);
  }
  return `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@graph': graph })}</script>`;
};

const shell = ({ title, description, path, current, body, faqSchema = '', serviceName = '', article = null, ogImage = '/assets/og.png', ogWidth = 1200, ogHeight = 630 }) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${gtmHead}<title>${title}</title><meta name="description" content="${description}"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1"><link rel="canonical" href="${domain}${path}"><link rel="icon" href="/assets/brand/favicon.svg?v=2" type="image/svg+xml"><link rel="alternate icon" href="/favicon.ico?v=2"><link rel="apple-touch-icon" href="/assets/brand/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><link rel="stylesheet" href="https://use.typekit.net/wrx5tvq.css"><link rel="stylesheet" href="/assets/site.css"><meta property="og:title" content="${title}"><meta property="og:description" content="${description}"><meta property="og:type" content="${article ? 'article' : 'website'}"><meta property="og:url" content="${domain}${path}"><meta property="og:image" content="${domain}${ogImage}"><meta property="og:image:width" content="${ogWidth}"><meta property="og:image:height" content="${ogHeight}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${domain}${ogImage}">${article ? `<meta property="article:published_time" content="${article.datePublished}"><meta property="article:modified_time" content="${modifiedDate}"><meta property="article:section" content="${article.section}">` : ''}${schema({ path, title, description, serviceName, article })}${faqSchema}</head><body>${gtmBody}${header(current)}<main id="main">${body}</main>${footer()}</body></html>`;

