const aboutBody = `${pageHero('About', 'About NuvelloWeb', 'Small studio.<br><span class="accent">Serious ownership.</span>', 'NuvelloWeb is a founder-led Los Angeles web and marketing studio built for businesses that want direct communication, thoughtful work, and fewer layers.')}
<section class="section"><div class="wrap split"><div><span class="eyebrow">The story</span><h2>Built from frustration with the usual agency experience.</h2><p>Too many businesses pay for attractive websites that never become useful business tools. Others get trapped between a disappearing freelancer and an agency process so layered that the people doing the work feel unreachable.</p><p>NuvelloWeb exists in the middle: the craft and attention of a focused studio, paired with the strategy and range needed to support a growing business.</p><p>We use the tools that fit the project. Sometimes that means a flexible CMS or commerce platform. Sometimes it means a lean custom build. The recommendation follows the goal—not ideology.</p></div><figure class="founder"><img src="/assets/Images/BenKrikler2.jpeg" alt="Benjamin Krikler, founder of NuvelloWeb"><figcaption><strong>Benjamin Krikler</strong><span>Founder, NuvelloWeb LLC</span></figcaption></figure></div></section>
<section class="section alt"><div class="wrap"><header class="section-head center"><span class="eyebrow">How we work</span><h2>Principles that show up in the work.</h2></header><div class="grid three"><div class="card"><span class="icon">01</span><h3>Clarity first</h3><p>Clear recommendations, plain-language explanations, and no mystery around scope or price.</p></div><div class="card"><span class="icon">02</span><h3>Outcomes over ornament</h3><p>Strong creative matters, but it has to serve the customer journey and the business goal.</p></div><div class="card"><span class="icon">03</span><h3>Direct accountability</h3><p>You know who owns the work, where it stands, and what happens next.</p></div><div class="card"><span class="icon">04</span><h3>Right-sized solutions</h3><p>No unnecessary complexity. No forcing every project into the same platform or package.</p></div><div class="card"><span class="icon">05</span><h3>Built to evolve</h3><p>Your digital presence should support the next phase, not become tomorrow’s constraint.</p></div><div class="card"><span class="icon">06</span><h3>Partnership mindset</h3><p>We bring a point of view, listen carefully, and make decisions with you—not at you.</p></div></div></div></section>${insightsPromo('See the thinking behind the work.')}${form('about','Not sure yet','Let’s build something worth growing.')}`;

